class ErrTrs(Exception):
    '''Base class for exceptions related to TRS'''
    pass


class ErrTrsError(ErrTrs):
    '''generic TRS error'''

    def __init__(self, err_data):
        super(ErrTrsError, self).__init__(str(err_data))
        self.err = err_data


class ErrTrsFailedFinishingHandler(ErrTrsError):
    '''await_finish method returned 0'''
    pass


class ErrTrsEventNotOccurred(ErrTrsError):
    '''message status is timeout'''
    pass


class ErrTrsEventOccurred(ErrTrsError):
    '''message status is success'''
    pass


class ErrTrsEventOccurredButParsingFailed(ErrTrsError):
    '''message status is failure'''
    pass


class ErrTrsNoSuchCommand(ErrTrsError):
    def __init__(self, device_name, cmd_name):
        err_msg = "device '%s' has no command named '%s'" % (device_name, cmd_name)
        super(ErrTrsNoSuchCommand, self).__init__(err_msg)


class ErrTrsCommandError(ErrTrsError):
    def __init__(self, device_name, cmd):
        self.device_name = device_name
        self.cmd = cmd
        err_msg = "device '%s' command '%s'" % (device_name, cmd)
        super(ErrTrsCommandError, self).__init__(err_msg)


class ErrTrsCommandNotStarted(ErrTrsCommandError):
    pass


class ErrTrsCommandFailed(ErrTrsCommandError):
    pass


class ErrTrsCommandTimeouted(ErrTrsCommandError):
    pass


class ErrTrsCommandSucceeded(ErrTrsCommandError):
    pass


class ErrTrsDeviceRegistration(ErrTrsError):
    pass
